import type { Metadata } from "next";
import Link from "next/link";
import { requireOrganization } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { DashboardShell } from "@/components/dashboard-shell";
export const metadata: Metadata = { title: "My Challenges" }; export const dynamic = "force-dynamic";
export default async function ChallengesPage({ searchParams }: { searchParams: Promise<{ status?: string }> }) {
  const saved = (await searchParams).status; const { organization } = await requireOrganization("vendor"); const supabase = await createClient();
  const { data: offers } = await supabase.from("offers").select("id,duel_id,status,annual_price,monthly_equivalent,currency,valid_until,submitted_at,vendor_products(product_name)").eq("vendor_organization_id", organization.organizationId).order("created_at", { ascending: false });
  return <DashboardShell area="Vendor" organization={organization.name}><div className="page-back"><Link href="/vendor">← Vendor dashboard</Link></div>{saved && <div className="notice-success">{saved === "submit" ? "Challenge submitted and locked." : "Challenge draft saved."}</div>}<div className="dashboard-heading"><div><span className="eyebrow">My Challenges</span><h1>Every offer, one ledger.</h1></div><Link className="button button-primary" href="/vendor/opportunities">Find opportunities</Link></div><div className="duel-list">{offers?.map((offer) => { const product = Array.isArray(offer.vendor_products) ? offer.vendor_products[0] : offer.vendor_products; return <Link className="duel-row challenge-table-row" href={`/vendor/opportunities/${offer.duel_id}/challenge`} key={offer.id}><span className="duel-number">{offer.id.slice(0,8)}</span><div><h2>{product?.product_name}</h2><p>Valid through {new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(offer.valid_until))}</p></div><div className="duel-spend"><strong>{new Intl.NumberFormat("en", { style: "currency", currency: offer.currency, maximumFractionDigits: 0 }).format(Number(offer.annual_price))}</strong><span>annual offer</span></div><span className={`badge badge-${offer.status}`}>{offer.status.replaceAll("_", " ")}</span><span>→</span></Link>; })}{!offers?.length && <div className="empty-panel"><h2>No challenges yet.</h2><p>Matching buyer opportunities will appear in the marketplace.</p></div>}</div></DashboardShell>;
}
